trait S { fn v(&self) -> i32; }
struct A; struct B;
impl S for A { fn v(&self) -> i32 { 1 } }
impl S for B { fn v(&self) -> i32 { 2 } }
let xs: Vec<Box<dyn S>> = vec![Box::new(A), Box::new(B)];
println!("{}", xs.iter().map(|x| x.v()).sum::<i32>());

